"""Pipe generation and motion."""
from units import PIPE_W, SCROLL, SPAWN_EVERY, SPAWN_X


def lcg(s):
    """Advance the LCG state once; return the new state."""
    return (1103515245 * s + 12345) % 2147483648


def spawn(t, s):
    """On a spawn tick return (pipe, new_state); otherwise (None, s)."""
    if t % SPAWN_EVERY != 0:
        return None, s
    s = lcg(s)
    gap_top = 40 + (s >> 8) % 80
    return {"x": SPAWN_X, "gap_top": gap_top, "passed": False}, s


def scroll(pipes):
    """Move every pipe left by SCROLL, in place."""
    for p in pipes:
        p["x"] -= SCROLL


def cull(pipes):
    """Drop every pipe fully off the left edge; return the rest."""
    return [p for p in pipes if p["x"] + PIPE_W > 0]

"""Deterministic simulation loop for flapsim."""
from collide import pipe_hit
from physics import step_bird
from units import BIRD_X, GLIDE_VY, PIPE_W, VY0, Y0
from world import cull, scroll, spawn


def run(seed, ticks, flaps, powerups=False):
    """Simulate one run, print TRACE lines, return the final state."""
    if powerups:
        raise NotImplementedError("powerups are future work (spec/07)")
    y, vy, score, alive = Y0, VY0, 0, True
    pipes, s, ticks_run = [], seed, 0
    every = max(1, ticks // 20)
    for t in range(ticks):
        pipe, s = spawn(t, s)
        if pipe is not None:
            pipes.append(pipe)
        y, vy, alive = step_bird(y, vy, flaps[t % len(flaps)] == "1")
        scroll(pipes)
        for p in pipes:
            if pipe_hit(y, p):
                alive = False
                break
        if alive:
            for p in pipes:
                if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
                    p["passed"] = True
                    score += 1
                    if abs(vy) <= GLIDE_VY:
                        score += 1
        pipes = cull(pipes)
        ticks_run = t + 1
        if t % every == 0:
            print("TRACE t=%04d y=%04d vy=%+05d score=%02d alive=%d"
                  % (t, y, vy, score, alive))
        if not alive:
            break
    return {"y": y, "vy": vy, "score": score, "alive": alive, "ticks_run": ticks_run}

