"""flapsim command line: argv parsing and output formatting."""
import contextlib
import io
import sys

import engine

USAGE = "usage: flapsim.py --seed S --ticks N --flaps BITS [--powerups]"

def selfcheck():
    cases = [(1, 7, 200, "0010", 8, 1), (2, 7, 120, "01", 0, 0),
             (3, 3, 200, "0001", 8, 1), (4, 11, 60, "1", 0, 0),
             (5, 2, 90, "0", 0, 0), (6, 5, 200, "0010", 8, 1)]
    for n, seed, ticks, flaps, es, ea in cases:
        with contextlib.redirect_stdout(io.StringIO()):
            st = engine.run(seed, ticks, flaps)
        gs, ga = st["score"], int(st["alive"])
        ok = "OK" if (gs, ga) == (es, ea) else "FAIL"
        print("EX%d seed=%d ticks=%d flaps=%s expect score=%02d alive=%d "
              "got score=%02d alive=%d %s" % (n, seed, ticks, flaps, es, ea, gs, ga, ok))

def main(argv):
    if "--selfcheck" in argv:
        if len(argv) != 1:
            sys.exit("usage: flapsim.py --selfcheck")
        selfcheck()
        return
    opts = {"flaps": "0", "powerups": False}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--powerups":
            opts["powerups"] = True
        elif a in ("--seed", "--ticks", "--flaps") and i + 1 < len(argv):
            opts[a[2:]] = argv[i + 1]
            i += 1
        else:
            sys.exit("unknown argument: %s" % a)
        i += 1
    if "seed" not in opts or "ticks" not in opts:
        sys.exit(USAGE)
    try:
        seed, ticks = int(opts["seed"]), int(opts["ticks"])
    except ValueError:
        sys.exit(USAGE)
    bits = opts["flaps"]
    if not bits or any(c not in "01" for c in bits):
        sys.exit("invalid --flaps bit string")
    if opts["powerups"]:
        sys.exit("--powerups is not implemented yet")
    st = engine.run(seed, ticks, bits)
    print("DIGEST seed=%d ticks=%d score=%d alive=%d y=%04d vy=%+05d ticks_run=%d" % (
        seed, ticks, st["score"], int(st["alive"]), st["y"], st["vy"], st["ticks_run"]))

if __name__ == "__main__":
    main(sys.argv[1:])

